import { describe, expect, test } from "bun:test";
import { render, TemplateRenderError, TemplateSyntaxError } from "../src/engine";

describe("interpolation", () => {
  test("escapes HTML and supports raw values", () => {
    const value = `&<>"'`;
    expect(render("{{value}}|{{{value}}}", { value })).toBe("&amp;&lt;&gt;&quot;&#39;|&<>\"'");
  });

  test("resolves nested paths and renders missing values empty", () => {
    expect(render("Hello {{user.name}} / {{missing}}!", { user: { name: "Ada" } })).toBe(
      "Hello Ada / !",
    );
  });

  test("rejects non-scalar interpolation", () => {
    expect(() => render("line 1\n{{user}}", { user: { name: "Ada" } })).toThrow(TemplateRenderError);
    expect(() => render("{{user}}", { user: {} })).toThrow(/line 1, column 1/);
  });
});

describe("blocks", () => {
  test("uses the specified truthiness rules", () => {
    const template = "{{#if value}}yes{{else}}no{{/if}}";
    for (const value of ["", 0, false, null, undefined, []]) {
      expect(render(template, { value })).toBe("no");
    }
    for (const value of ["0", {}, [0], true, NaN]) {
      expect(render(template, { value })).toBe("yes");
    }
  });

  test("iterates, exposes index, and falls back to the root", () => {
    const template = "{{#each users}}{{@index}}={{name}}/{{title}};{{else}}none{{/each}}";
    expect(render(template, { title: "member", users: [{ name: "A" }, { name: "B" }] })).toBe(
      "0=A/member;1=B/member;",
    );
    expect(render(template, { title: "member", users: [] })).toBe("none");
  });

  test("supports nested loops and this", () => {
    const template = "{{#each rows}}[{{#each this}}{{@index}}:{{this}}{{else}}empty{{/each}}]{{/each}}";
    expect(render(template, { rows: [["a", "b"], []] })).toBe("[0:a1:b][empty]");
  });

  test("supports nested conditionals", () => {
    expect(render("{{#if a}}A{{#if b}}B{{else}}C{{/if}}{{else}}D{{/if}}", { a: true, b: false })).toBe("AC");
  });
});

describe("syntax and whitespace", () => {
  test("preserves whitespace and removes comments", () => {
    expect(render(" a \n{{! gone }}\t b ", {})).toBe(" a \n\t b ");
  });

  test("reports structural mistakes with positions", () => {
    const cases = [
      "{{#wat x}}{{/wat}}",
      "{{else}}",
      "{{#if x}}{{else}}{{else}}{{/if}}",
      "{{#if x}}\n{{/each}}",
      "{{#each x}}",
      "{{/if}}",
    ];
    for (const template of cases) {
      expect(() => render(template, {})).toThrow(TemplateSyntaxError);
      expect(() => render(template, {})).toThrow(/line \d+, column \d+/);
    }
  });
});

