import { describe, expect, test } from "bun:test";

const decoder = new TextDecoder();

async function runCli(args: string[]) {
  const process = Bun.spawn([process.execPath, "run", "src/cli.ts", ...args], {
    cwd: import.meta.dir + "/..",
    stdout: "pipe",
    stderr: "pipe",
  });
  const [stdout, stderr, exitCode] = await Promise.all([
    new Response(process.stdout).arrayBuffer(),
    new Response(process.stderr).arrayBuffer(),
    process.exited,
  ]);
  return {
    stdout: decoder.decode(stdout),
    stderr: decoder.decode(stderr),
    exitCode,
  };
}

describe("CLI", () => {
  test("renders files to stdout without diagnostics", async () => {
    const result = await runCli(["test/fixtures/cli-template.txt", "test/fixtures/cli-data.json"]);
